    void typingNarrowsTheListAndUpdatesTheAddressBar() {
        open("/");
        assertEquals("Showing 500 of 500", summary().textContent().strip());

        nameField().pressSequentially("makinen");
        page.waitForFunction("() => new URL(location.href).searchParams.get('name') === 'makinen'");

        assertEquals("Showing 15 of 500", summary().textContent().strip());
        assertEquals("/?name=makinen", pathAndQuery());
    }

    @Test
    void typingDoesNotQueryTheBackendOncePerKeystroke() {
        open("/");
        queryLog.clear();

        nameField().pressSequentially("nadia makinen");
        page.waitForFunction("() => new URL(location.href).searchParams.get('name') === 'nadia makinen'");
        page.waitForTimeout(500);

        assertTrue(queryLog.countQueries().size() <= 3,
                "Typing 13 characters ran " + queryLog.countQueries().size() + " count queries");
        assertTrue(queryLog.pageQueries().size() <= 3,
                "Typing 13 characters ran " + queryLog.pageQueries().size() + " page queries");
    }

    @Test
    void clearingTheFilterRemovesItFromTheAddressBar() {
        open("/?name=ada&status=PENDING");

