@@ -0,0 +1,63 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+
+/**
+ * Which customers a query asks for.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ *   <li>{@code name}: every whitespace-separated term appears, ignoring case and
+ *       accents, in the customer's first name or last name. An empty name matches
+ *       every customer.</li>
+ *   <li>{@code statuses}: the customer has one of these statuses. Empty means
+ *       every status.</li>
+ * </ul>
+ *
+ * @param name     the text typed into the name filter; may be empty
+ * @param statuses the statuses to show, in declaration order; may be empty
+ */
+public record CustomerFilter(String name, List<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter NONE = new CustomerFilter("", List.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? List.of()
+                : statuses.stream().distinct().sorted().toList();
+    }
+
+    /** Returns {@code true} if {@code customer} satisfies both parts of this filter. */
+    public boolean matches(Customer customer) {
+        return statusMatches(customer) && nameMatches(customer);
+    }
+
+    private boolean statusMatches(Customer customer) {
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    private boolean nameMatches(Customer customer) {
+        List<String> terms = terms(name);
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private static List<String> terms(String text) {
+        return List.of(fold(text).split("[\\s\\p{Z}]+")).stream()
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /** Lower-cases and strips accents, so {@code Mäkinen} folds to {@code makinen}. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return decomposed.replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
+    }
+}
